# Tiny CPU-scheduling simulator: FCFS, SJF, SRTF, Round Robin on one CPU.
# Ignores context-switch cost. Ties broken by arrival order.
from collections import deque

JOBS = [  # (name, arrival, burst)
    ("P1", 0, 8),
    ("P2", 1, 4),
    ("P3", 2, 9),
    ("P4", 3, 5),
]

def simulate(policy, quantum=4):
    t, timeline = 0, []                         # timeline: (start, end, name)
    left = {n: b for n, a, b in JOBS}
    arrive = {n: a for n, a, b in JOBS}
    first_run, finish = {}, {}
    queue, pending = deque(), deque(sorted(JOBS, key=lambda j: j[1]))

    def admit(now):
        while pending and pending[0][1] <= now:
            queue.append(pending.popleft()[0])

    admit(0)
    current = None
    while len(finish) < len(JOBS):
        if not queue and current is None:       # CPU idle until next arrival
            t = pending[0][1]; admit(t); continue
        if policy in ("FCFS", "RR"):
            if current is None: current = queue.popleft()
        elif policy == "SJF":                   # non-preemptive: choose only when CPU frees
            if current is None:
                current = min(queue, key=lambda n: left[n]); queue.remove(current)
        elif policy == "SRTF":                  # preemptive: re-choose every time unit
            if current is not None: queue.appendleft(current)
            current = min(queue, key=lambda n: left[n]); queue.remove(current)

        run = {"FCFS": left[current], "SJF": left[current],
               "RR": min(quantum, left[current]), "SRTF": 1}[policy]
        first_run.setdefault(current, t)
        if timeline and timeline[-1][2] == current and timeline[-1][1] == t:
            timeline[-1] = (timeline[-1][0], t + run, current)  # merge slices
        else:
            timeline.append((t, t + run, current))
        t += run; left[current] -= run
        admit(t)                                # arrivals join the queue before the preempted job
        if left[current] == 0:
            finish[current] = t; current = None
        elif policy == "RR":
            queue.append(current); current = None

    print(f"\n{policy}{f' (q={quantum})' if policy == 'RR' else ''}")
    print("  Gantt: " + " | ".join(f"{n} {s}-{e}" for s, e, n in timeline))
    tat = {n: finish[n] - arrive[n] for n in finish}
    wait = {n: tat[n] - b for n, a, b in JOBS}
    resp = {n: first_run[n] - arrive[n] for n in finish}
    for n, a, b in JOBS:
        print(f"  {n}: finish={finish[n]:2} turnaround={tat[n]:2} wait={wait[n]:2} response={resp[n]:2}")
    avg = lambda d: sum(d.values()) / len(d)
    print(f"  avg turnaround={avg(tat):.2f}  avg wait={avg(wait):.2f}  avg response={avg(resp):.2f}")

for p in ("FCFS", "SJF", "SRTF", "RR"):
    simulate(p)

# Linux only. Two CPU-bound processes forced onto ONE core: how does nice split the CPU?
import os, time, multiprocessing as mp

def spin(niceness, seconds, out):
    os.sched_setaffinity(0, {0})       # pin to CPU 0 so they must compete
    os.nice(niceness)                  # raise niceness = lower weight
    end, n = time.time() + seconds, 0
    while time.time() < end:
        n += 1
    out.put((niceness, n))

if __name__ == "__main__":
    q = mp.Queue()
    procs = [mp.Process(target=spin, args=(nv, 3, q)) for nv in (0, 5)]
    for p in procs: p.start()
    for p in procs: p.join()
    res = dict(q.get() for _ in procs)
    total = sum(res.values())
    for nv, n in sorted(res.items()):
        print(f"nice {nv}: {n:>11,} loops  ({100 * n / total:.0f}% of the core)")
    print(f"ratio ≈ {res[0] / res[5]:.2f}   (kernel weights 1024 / 335 = {1024/335:.2f})")

// Oversubscription: 4x more CPU-bound threads than cores vs. a pool sized to the cores.
const { Worker, isMainThread, parentPort } = require('worker_threads');
const os = require('os');

if (!isMainThread) {
  parentPort.on('message', (n) => {          // a fixed chunk of pure CPU work
    let x = 0;
    for (let i = 0; i < n; i++) x = (x + i * i) % 1_000_003;
    parentPort.postMessage(x);
  });
} else {
  const CORES = os.availableParallelism();   // respects CPU affinity on Linux
  const TASKS = CORES * 4;
  const WORK = 5_000_000;

  async function run(poolSize) {
    const workers = Array.from({ length: poolSize }, () => new Worker(__filename));
    const start = performance.now();
    const done = [];
    let next = 0;
    await Promise.all(workers.map((w) => new Promise((resolve) => {
      const feed = () => {
        if (next >= TASKS) return resolve();
        next++;
        w.once('message', () => { done.push(performance.now() - start); feed(); });
        w.postMessage(WORK);
      };
      feed();
    })));
    workers.forEach((w) => w.terminate());
    const total = Math.max(...done);
    const mean = done.reduce((a, b) => a + b, 0) / done.length;
    console.log(`${String(poolSize).padStart(3)} threads: makespan ${total.toFixed(0)} ms, ` +
                `mean task completion ${mean.toFixed(0)} ms`);
  }

  (async () => {
    console.log(`${CORES} cores, ${TASKS} equal CPU-bound tasks`);
    await run(CORES);        // pool = cores: tasks finish in waves
    await run(TASKS);        // one thread per task: everyone time-slices, everyone finishes late
  })();
}
